<template>
<section><div class="page-head"><div><span class="eyebrow">Add-on</span><h1 class="page-title">{{($root.selectedAddonData||{}).name}}</h1><p class="muted">{{($root.selectedAddonData||{}).description}}</p></div><button class="button-secondary" @click="$emit('navigate','addons')">← Add-ons</button></div><div class="card"><div class="row"><span class="brand-mark">{{($root.selectedAddonData||{}).icon}}</span><div class="grow"><h2>{{($root.selectedAddonData||{}).name}}</h2><p class="muted">Version {{($root.selectedAddonData||{}).version}} · LogoRemakeFour</p></div><button v-if="!state.installed.includes($root.route.addonId)" class="button" @click="$emit('action',{action:'install',payload:$root.route.addonId})">Install</button><button v-else class="button" @click="$emit('action',{action:'open-addon',payload:$root.route.addonId})">Open</button></div><p class="muted" style="margin-top:20px">Use this add-on to connect supported services. External sign-in and media playback are handled by their respective providers.</p><div class="row"><button class="button-secondary" @click="$emit('action',{action:'addon-settings',payload:$root.route.addonId})">Settings</button><button class="quiet" @click="$emit('action',{action:'remove',payload:$root.route.addonId})">Uninstall</button></div></div></section>
